content:
Looking at the task requirements, I need to create separate log bucket and reader identity resources for dev and prod, following the patterns established in the existing `main.ts` files. The key points are:

1. Use `SecureBucket` for the logs bucket (versioning/encryption/public-access block are pinned unconditionally)
2. Use `ReaderIam` scoped only to the logs bucket with `additionalActions: ["s3:PutObject"]` (baseline already includes `s3:GetObject`)
3. Mirror the trust configuration from each environment's existing `reader` call
4. Keep dev and prod independent with separate files

`src/envs/dev/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";

// ── Application logs bucket ──────────────────────────────────────────────────

export const logs = SecureBucket({
  name: "myapp-logs-dev",
  env: ENV,
  region: REGION,
});

// ── Service-account identity for logs ────────────────────────────────────────

export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: "myapp-logs-dev",
  trust: { mode: "account", accountID: "123456789012" },
  programmaticAccess: true,
  additionalActions: ["s3:PutObject"],
});
```

`src/envs/prod/infra/logs.ts`
```typescript
import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

// ── Application logs bucket ──────────────────────────────────────────────────

export const logs = SecureBucket({
  name: "myapp-logs-prod",
  env: ENV,
  region: REGION,
});

// ── Service-account identity for logs ────────────────────────────────────────

export const logsReader = ReaderIam({
  name: "myapp-prod-logs",
  env: ENV,
  bucketName: "myapp-logs-prod",
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  programmaticAccess: false,
  podIdentity: {
    clusterName: "myapp-prod",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
});
```

Both files will be discovered and built alongside their respective `main.ts` files. The dev logs reader uses account-based access with an IAM user (matching dev's existing reader), while prod uses OIDC trust with pod identity (matching prod's existing reader). Each reader is scoped exclusively to its logs bucket with enumerated, non-wildcard permissions.
